            [JsonPropertyName("orthoBasis")] public List<BasisCase>? OrthoBasis { get; set; }
            [JsonPropertyName("minimumCurvature")] public MinimumCurvatureCase? MinimumCurvature { get; set; }
            [JsonPropertyName("sectionTangents")] public List<SectionCase>? SectionTangents { get; set; }
            [JsonPropertyName("rotAlign")] public List<RotationCase>? RotAlign { get; set; }
            [JsonPropertyName("wellInputs")] public List<WellCase>? WellInputs { get; set; }
            [JsonPropertyName("closedFormFits")] public List<FitCase>? ClosedFormFits { get; set; }
            [JsonPropertyName("segmentation")] public List<SegmentationCase>? Segmentation { get; set; }
            [JsonPropertyName("endToEnd")] public List<EndToEndCase>? EndToEnd { get; set; }
        }

