            [JsonPropertyName("sampleStationIndices")] public List<int>? SampleStationIndices { get; set; }
            [JsonPropertyName("referencePositionsAtSamples")] public List<List<double>>? ReferencePositionsAtSamples { get; set; }
            [JsonPropertyName("originalPositionsAtSamples")] public List<List<double>>? OriginalPositionsAtSamples { get; set; }
